next_generation <- function(grid) {
  nr <- nrow(grid)
  nc <- ncol(grid)
  result <- matrix(0, nr, nc)
  for (i in seq_len(nr)) {
    for (j in seq_len(nc)) {
      alive <- 0
      for (di in -1:1) {
        for (dj in -1:1) {
          if (di == 0 && dj == 0) next
          ni <- i + di
          nj <- j + dj
          if (ni >= 1 && ni <= nr && nj >= 1 && nj <= nc) alive <- alive + grid[ni, nj]
        }
      }
      if (grid[i, j] == 1) {
        result[i, j] <- as.numeric(alive %in% c(2, 3))
      } else {
        result[i, j] <- as.numeric(alive == 3)
      }
    }
  }
  result
}
